def serialize(self, value, display=False):
    if value is True:
        return "true"
    elif value in (False, None):
        return "false"
    else:
        raise ValueError(f"{value!r} is not a boolean")

def serialize(self, value, display=False):
    if value is None:
        return ""
    if isinstance(value, _TransformedValue):
        value = value.original
    return encode(value)
